// Generated from public/fonts (SIL OFL). Embedded so OG rendering needs no network, fs, or global-scope I/O on Workers.
// Fraunces files are static instances (opsz 144, SOFT 100, WONK 1) of the site display face; Satori cannot set variable axes.
export const FRAUNCES_800_B64 =
  ''
export const FRAUNCES_700_ITALIC_B64 =
  ''
export const WORK_SANS_400_B64 =
  ''
export const JETBRAINS_MONO_700_B64 =
  ''
// Neonderthaw is subset to the letters of "groovy", the only word the cards set in neon.
export const NEONDERTHAW_GROOVY_B64 =
  ''
export function decodeFont(b64: string): ArrayBuffer {
  const bin = atob(b64)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  return bytes.buffer
}
